"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { savePreferences } from "@/lib/actions";
import type { ActionResult } from "@/lib/errors";
import {
  getRoleShortcutLimit,
  normalizeRole,
  roleShortcutError,
} from "@/lib/roles";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { useUnsavedChanges } from "@/components/forms";

export function useRolePreferences(roles: string[]) {
  const [values, setValues] = useState(roles);
  const [savedValues, setSavedValues] = useState(roles);
  const [custom, setCustom] = useState("");
  const [editing, setEditing] = useState<string | null>(null);
  const [result, setResult] = useState<ActionResult>();
  const [pending, start] = useTransition();
  const { effectivePlan: plan } = useWorkspaceEntitlements();
  const limit = getRoleShortcutLimit(plan);
  const atLimit = values.length >= limit;
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);
  const error = Object.entries(result?.fieldErrors ?? {}).find(([key]) =>
    key.startsWith("preferredRoles"),
  )?.[1];

  useUnsavedChanges(
    custom.length > 0 ||
      editing !== null ||
      JSON.stringify(values) !== JSON.stringify(savedValues),
  );
  useEffect(() => {
    if (!pending && error) inputRef.current?.focus();
  }, [pending, error, result]);

  function fail(message: string) {
    setResult({ ok: false, message, fieldErrors: { preferredRoles: message } });
  }
  function validate(next: string[]) {
    if (next.some((role) => !role.trim())) return "Enter a role name.";
    if (next.some((role) => role.trim().length > 160))
      return "Use 160 characters or fewer for each role.";
    if (new Set(next.map(normalizeRole)).size !== next.length)
      return "Choose unique roles. This role is already selected.";
    return roleShortcutError(plan, next, savedValues);
  }
  function applyDraft(role: string): string[] | undefined {
    const value = role.trim();
    if (!value) {
      fail("Enter a role name.");
      return;
    }
    const next =
      editing === null
        ? [...values, value]
        : values.map((current) => (current === editing ? value : current));
    const message = validate(next);
    if (message) {
      fail(message);
      return;
    }
    return next;
  }
  function cancel() {
    setEditing(null);
    setCustom("");
    setResult(undefined);
  }
  function add(role = custom) {
    if (pending) return;
    const next = applyDraft(role);
    if (!next) return;
    setValues(next);
    cancel();
    inputRef.current?.focus();
  }
  function toggle(role: string) {
    if (pending) return;
    if (!values.includes(role)) {
      // Suggestions add a selection independently of an input draft.
      const next = [...values, role];
      const message = validate(next);
      if (message) return fail(message);
      setValues(next);
      setResult(undefined);
      return;
    }
    setValues(values.filter((value) => value !== role));
    setResult(undefined);
    if (editing === role) cancel();
  }
  function edit(role: string) {
    setEditing(role);
    setCustom(role);
    setResult(undefined);
    inputRef.current?.focus();
  }
  function save() {
    if (pending) return;
    const next =
      custom.trim() || editing !== null ? applyDraft(custom) : values;
    if (!next) return;
    const message = validate(next);
    if (message) return fail(message);
    setResult(undefined);
    start(async () => {
      try {
        const response = await savePreferences({ preferredRoles: next });
        setResult(response);
        if (response.ok) {
          setValues(next);
          setSavedValues(next);
          setCustom("");
          setEditing(null);
          router.refresh();
        }
      } catch {
        setResult({
          ok: false,
          message: "Could not save preferences. Try again.",
        });
      }
    });
  }
  return {
    values,
    custom,
    editing,
    result,
    pending,
    plan,
    limit,
    atLimit,
    inputRef,
    error,
    add,
    toggle,
    edit,
    cancel,
    save,
    change(text: string) {
      setCustom(text);
      setResult(undefined);
    },
  };
}
